//! Directed acyclic graphs: topological orders, transitive closure and
//! reduction, longest paths, dominators, and lowest common ancestors.
//!
//! Sources:
//! - Topological sorting by repeatedly removing nodes without incoming
//!   arcs (Kahn 1962, `kahn1962topological`), one generation (all nodes
//!   whose remaining in-degree is zero) at a time. Every topological order
//!   of a DAG is generated by the backtracking algorithm of Knuth and
//!   Szwarcfiter (1974, `knuth1974structured`), which NetworkX's
//!   `all_topological_sorts` implements; this module runs the same steps,
//!   so the orders come in the same sequence.
//! - The transitive closure adds an arc u -> v whenever v is reachable
//!   from u (Warshall 1962, `warshall1962theorem`); it is computed one
//!   strongly connected component at a time in reverse topological order,
//!   with reachable sets as bit vectors (Purdom 1970, `purdom1970transitive`).
//!   The transitive reduction of a DAG, the smallest graph with the same
//!   reachability, keeps the arcs u -> v for which no other path leads
//!   from u to v (Aho, Garey, and Ullman 1972, `aho1972transitive`).
//! - Longest paths in a DAG by dynamic programming over a topological
//!   order (Sedgewick and Wayne 2011, `sedgewick2011algorithms`, section
//!   4.4).
//! - Immediate dominators by the iterative algorithm of Cooper, Harvey, and
//!   Kennedy (2001, `cooper2001simple`) over a reverse postorder, and
//!   dominance frontiers by their walk up the dominator tree from the
//!   predecessors of each join node (Cytron et al. 1991,
//!   `cytron1991efficiently`, define the frontier).
//! - Lowest common ancestors: in a DAG, a common ancestor of u and v none
//!   of whose children is also a common ancestor (Aho, Hopcroft, and Ullman
//!   1976, `aho1976finding`; Bender et al. 2005, `bender2005lowest`); in a
//!   tree it is unique and found here by binary lifting over depths.
//!
//! Conventions (NetworkX 3.7, `hagberg2008exploring`, unless noted):
//! - Directed networks only; a cycle (a self-loop included) makes the
//!   DAG functions fail, as NetworkX raises `NetworkXUnfeasible`.
//!   Parallel arcs count once for orders, closure, reduction, and
//!   dominators; a longest path uses the heaviest of parallel arcs.
//! - Orders depend on the neighbour order ([`crate::order`]): generation
//!   by generation, nodes enter a generation in the order their last
//!   parent releases them, roots in node order. With the input order these
//!   are NetworkX's `topological_generations` and `topological_sort`, and
//!   `all_topological_sorts` comes in NetworkX's sequence.
//!   `lexicographical_topological_sort` (always the smallest available
//!   node) does not depend on the neighbour order.
//! - The transitive closure is reported as its set of pairs. With
//!   `Reflexive::Cycles` (NetworkX's default `reflexive=False`), (v, v) is
//!   included when v lies on a cycle; `Reflexive::Never` (`None`) adds no
//!   (v, v) beyond self-loops already present; `Reflexive::Always`
//!   (`True`) adds every (v, v). Unlike the other functions here it accepts
//!   cycles.
//! - Longest paths: arc weights with `weighted` (NetworkX's default
//!   attribute "weight"), else 1; negative arcs never extend a path
//!   (NetworkX starts afresh when the best extension is negative). Ties
//!   go to the first predecessor in the neighbour order and to the first
//!   end node in topological order, as in NetworkX. An empty network has
//!   the empty path, of length 0.
//! - Dominators: nodes unreachable from the start have no immediate
//!   dominator; the start's immediate dominator is itself (NetworkX 3.7
//!   leaves the start out of its result). Dominance frontiers are given
//!   for nodes reachable from the start.
//! - Lowest common ancestors: every node is its own ancestor. In a DAG with
//!   several lowest common ancestors of a pair, the walk starts from the
//!   common ancestor of smallest index and moves to the first child (in the
//!   neighbour order) that is still a common ancestor; NetworkX starts
//!   from an arbitrary common ancestor (the first in Python's set
//!   order), so the two agree whenever the answer is unique, as in a tree.

use crate::bitset::BitMatrix;
use crate::error::{Error, Result};
use crate::graph::Graph;
use crate::metrics::connectivity::strong_components;
use crate::order::{rows, Direction, NeighborOrder, Rows};

fn directed(g: &Graph, what: &str) -> Result<()> {
    if g.is_directed() {
        Ok(())
    } else {
        Err(Error::InvalidArgument(format!(
            "{what} is not defined for undirected networks"
        )))
    }
}

fn cycle_error() -> Error {
    Error::InvalidArgument("the network contains a cycle, so it is not a DAG".into())
}

fn has_loop(g: &Graph) -> bool {
    g.edge_sources()
        .iter()
        .zip(g.edge_targets())
        .any(|(a, b)| a == b)
}

/// Topological generations: the roots, then the nodes all of whose
/// parents are in earlier generations, and so on. See the module
/// documentation.
pub fn topological_generations(g: &Graph, order: NeighborOrder) -> Result<Vec<Vec<u32>>> {
    directed(g, "a topological order")?;
    if has_loop(g) {
        return Err(cycle_error());
    }
    let n = g.node_count();
    let out = rows(g, Direction::Out, order, true, true);
    let mut indeg = vec![0usize; n];
    for v in 0..n {
        for &w in out.neighbors(v) {
            indeg[w as usize] += 1;
        }
    }
    let mut current: Vec<u32> = (0..n as u32).filter(|&v| indeg[v as usize] == 0).collect();
    let mut generations = Vec::new();
    let mut done = 0;
    while !current.is_empty() {
        let mut next = Vec::new();
        for &v in &current {
            for &w in out.neighbors(v as usize) {
                let w = w as usize;
                indeg[w] -= 1;
                if indeg[w] == 0 {
                    next.push(w as u32);
                }
            }
        }
        done += current.len();
        generations.push(std::mem::replace(&mut current, next));
    }
    if done < n {
        return Err(cycle_error());
    }
    Ok(generations)
}

/// A topological order: the generations in turn. See the module
/// documentation.
pub fn topological_sort(g: &Graph, order: NeighborOrder) -> Result<Vec<u32>> {
    Ok(topological_generations(g, order)?
        .into_iter()
        .flatten()
        .collect())
}

/// The topological order that always takes the smallest available node
/// (NetworkX's `lexicographical_topological_sort` without a key).
pub fn lexicographical_topological_sort(g: &Graph) -> Result<Vec<u32>> {
    directed(g, "a topological order")?;
    if has_loop(g) {
        return Err(cycle_error());
    }
    let n = g.node_count();
    let out = rows(g, Direction::Out, NeighborOrder::Sorted, true, true);
    let mut indeg = vec![0usize; n];
    for v in 0..n {
        for &w in out.neighbors(v) {
            indeg[w as usize] += 1;
        }
    }
    let mut heap: std::collections::BinaryHeap<std::cmp::Reverse<u32>> = (0..n as u32)
        .filter(|&v| indeg[v as usize] == 0)
        .map(std::cmp::Reverse)
        .collect();
    let mut result = Vec::with_capacity(n);
    while let Some(std::cmp::Reverse(v)) = heap.pop() {
        result.push(v);
        for &w in out.neighbors(v as usize) {
            indeg[w as usize] -= 1;
            if indeg[w as usize] == 0 {
                heap.push(std::cmp::Reverse(w));
            }
        }
    }
    if result.len() < n {
        return Err(cycle_error());
    }
    Ok(result)
}

/// Every topological order, in the sequence of Knuth and Szwarcfiter's
/// algorithm (NetworkX's), stopping after `limit` orders when given.
pub fn all_topological_sorts(
    g: &Graph,
    order: NeighborOrder,
    limit: Option<usize>,
) -> Result<Vec<Vec<u32>>> {
    directed(g, "a topological order")?;
    if has_loop(g) {
        return Err(cycle_error());
    }
    let n = g.node_count();
    // Arcs with multiplicity, as NetworkX's in-degrees and out-edges count
    // parallel arcs.
    let out = rows(g, Direction::Out, order, true, true);
    let mut count = vec![0i64; n];
    for v in 0..n {
        for (&w, &c) in out.neighbors(v).iter().zip(out.counts(v)) {
            count[w as usize] += c as i64;
        }
    }
    let mut deque: std::collections::VecDeque<u32> =
        (0..n as u32).filter(|&v| count[v as usize] == 0).collect();
    let mut bases: Vec<u32> = Vec::new();
    let mut current: Vec<u32> = Vec::new();
    let mut result: Vec<Vec<u32>> = Vec::new();
    loop {
        if current.len() == n {
            result.push(current.clone());
            if matches!(limit, Some(l) if result.len() >= l) {
                break;
            }
            while let Some(q) = current.pop() {
                for (&j, &c) in out.neighbors(q as usize).iter().zip(out.counts(q as usize)) {
                    count[j as usize] += c as i64;
                }
                while let Some(&back) = deque.back() {
                    if count[back as usize] > 0 {
                        deque.pop_back();
                    } else {
                        break;
                    }
                }
                deque.push_front(q);
                if deque.back() == bases.last() {
                    bases.pop();
                } else {
                    break;
                }
            }
        } else {
            let q = deque.pop_back().ok_or_else(cycle_error)?;
            for (&j, &c) in out.neighbors(q as usize).iter().zip(out.counts(q as usize)) {
                count[j as usize] -= c as i64;
                if count[j as usize] == 0 {
                    deque.push_back(j);
                }
            }
            current.push(q);
            if bases.len() < current.len() {
                bases.push(q);
            }
        }
        if bases.is_empty() {
            break;
        }
    }
    Ok(result)
}

/// Whether the network is a directed acyclic graph (false for an
/// undirected network, as in NetworkX).
pub fn is_directed_acyclic_graph(g: &Graph) -> bool {
    g.is_directed() && topological_generations(g, NeighborOrder::Sorted).is_ok()
}

/// Which (v, v) pairs a transitive closure includes. See the module
/// documentation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Reflexive {
    /// (v, v) when v lies on a cycle (NetworkX's `reflexive=False`).
    #[default]
    Cycles,
    /// No (v, v) beyond existing self-loops (NetworkX's `reflexive=None`).
    Never,
    /// Every (v, v) (NetworkX's `reflexive=True`).
    Always,
}

impl Reflexive {
    /// Decodes the C interface codes: 0 = cycles, 1 = never, 2 = always.
    pub fn from_code(code: i32) -> Result<Reflexive> {
        match code {
            0 => Ok(Reflexive::Cycles),
            1 => Ok(Reflexive::Never),
            2 => Ok(Reflexive::Always),
            _ => Err(Error::InvalidArgument(format!(
                "unknown reflexive code {code}"
            ))),
        }
    }
}

/// For every node, the nodes reachable from it by a path of at least one
/// arc, as rows of a bit matrix.
fn reachability(g: &Graph) -> BitMatrix {
    let n = g.node_count();
    let comp = strong_components(g, NeighborOrder::Sorted);
    let k = comp.iter().map(|&c| c as usize + 1).max().unwrap_or(0);
    // Members of each component and whether it has an internal arc.
    let mut members: Vec<Vec<u32>> = vec![Vec::new(); k];
    for v in 0..n {
        members[comp[v] as usize].push(v as u32);
    }
    let mut cyclic = vec![false; k];
    let mut succ: Vec<Vec<u32>> = vec![Vec::new(); k];
    for (&a, &b) in g.edge_sources().iter().zip(g.edge_targets()) {
        let (ca, cb) = (comp[a as usize] as usize, comp[b as usize] as usize);
        if ca == cb {
            cyclic[ca] = true;
        } else {
            succ[ca].push(cb as u32);
        }
    }
    // Component labels are a reverse topological order: successors have
    // smaller labels, so increasing labels see successors first.
    let words = (n + 63) / 64;
    let mut nodes_of: Vec<Vec<u64>> = vec![vec![0u64; words]; k];
    for c in 0..k {
        let mut set = vec![0u64; words];
        for &d in &succ[c] {
            let d = d as usize;
            for (x, y) in set.iter_mut().zip(&nodes_of[d]) {
                *x |= *y;
            }
            for &v in &members[d] {
                set[v as usize / 64] |= 1u64 << (v % 64);
            }
        }
        if cyclic[c] {
            for &v in &members[c] {
                set[v as usize / 64] |= 1u64 << (v % 64);
            }
        }
        nodes_of[c] = set;
    }
    let mut out = BitMatrix::new(n);
    for v in 0..n {
        let set = &nodes_of[comp[v] as usize];
        for (w, &word) in set.iter().enumerate() {
            let mut bits = word;
            while bits != 0 {
                let b = bits.trailing_zeros() as usize;
                bits &= bits - 1;
                out.set(v, w * 64 + b);
            }
        }
    }
    out
}

/// The pairs (u, v) of the transitive closure, sorted. See the module
/// documentation.
pub fn transitive_closure(g: &Graph, reflexive: Reflexive) -> Result<Vec<(u32, u32)>> {
    directed(g, "the transitive closure")?;
    let n = g.node_count();
    let reach = reachability(g);
    let mut loops = vec![false; n];
    for (&a, &b) in g.edge_sources().iter().zip(g.edge_targets()) {
        if a == b {
            loops[a as usize] = true;
        }
    }
    let mut pairs = Vec::new();
    for (u, &has_loop) in loops.iter().enumerate() {
        for v in 0..n {
            let include = if u == v {
                match reflexive {
                    Reflexive::Cycles => reach.get(u, u),
                    Reflexive::Never => has_loop,
                    Reflexive::Always => true,
                }
            } else {
                reach.get(u, v)
            };
            if include {
                pairs.push((u as u32, v as u32));
            }
        }
    }
    Ok(pairs)
}

/// The arcs (u, v) of the transitive reduction of a DAG, sorted.
pub fn transitive_reduction(g: &Graph) -> Result<Vec<(u32, u32)>> {
    directed(g, "the transitive reduction")?;
    if !is_directed_acyclic_graph(g) {
        return Err(cycle_error());
    }
    let n = g.node_count();
    let reach = reachability(g);
    let out = rows(g, Direction::Out, NeighborOrder::Sorted, true, true);
    let words = (n + 63) / 64;
    let mut pairs = Vec::new();
    let mut covered = vec![0u64; words];
    for u in 0..n {
        for c in covered.iter_mut() {
            *c = 0;
        }
        for &w in out.neighbors(u) {
            for (c, &r) in covered.iter_mut().zip(reach.row(w as usize)) {
                *c |= r;
            }
        }
        for &v in out.neighbors(u) {
            if covered[v as usize / 64] >> (v % 64) & 1 == 0 {
                pairs.push((u as u32, v));
            }
        }
    }
    Ok(pairs)
}

/// A longest path of a DAG and its length. See the module documentation.
pub fn dag_longest_path(
    g: &Graph,
    weighted: bool,
    order: NeighborOrder,
) -> Result<(Vec<u32>, f64)> {
    directed(g, "a longest path in a DAG")?;
    let n = g.node_count();
    if n == 0 {
        return Ok((Vec::new(), 0.0));
    }
    let topo = topological_sort(g, order)?;
    let weights = if weighted {
        Some(g.edge_weights().ok_or(Error::MissingWeights)?)
    } else {
        None
    };
    // Predecessors in order with the heaviest parallel arc.
    let pred = rows(g, Direction::In, order, true, false);
    let mut best_pred: Vec<Vec<(u32, f64)>> = vec![Vec::new(); n];
    for (v, list) in best_pred.iter_mut().enumerate() {
        for (&u, &e) in pred.neighbors(v).iter().zip(pred.edges(v)) {
            let w = weights.map_or(1.0, |w| w[e as usize]);
            match list.iter_mut().find(|x| x.0 == u) {
                Some(x) => x.1 = x.1.max(w),
                None => list.push((u, w)),
            }
        }
    }
    let mut dist = vec![0.0f64; n];
    let mut from = vec![u32::MAX; n];
    for &v in &topo {
        let v = v as usize;
        let mut best: Option<(f64, u32)> = None;
        for &(u, w) in &best_pred[v] {
            let d = dist[u as usize] + w;
            if best.map_or(true, |b| d > b.0) {
                best = Some((d, u));
            }
        }
        match best {
            Some((d, u)) if d >= 0.0 => {
                dist[v] = d;
                from[v] = u;
            }
            _ => {
                dist[v] = 0.0;
                from[v] = v as u32;
            }
        }
    }
    let mut end = topo[0] as usize;
    for &v in &topo {
        if dist[v as usize] > dist[end] {
            end = v as usize;
        }
    }
    let mut path = vec![end as u32];
    let mut v = end;
    while from[v] as usize != v {
        v = from[v] as usize;
        path.push(v as u32);
    }
    path.reverse();
    // The length sums the path's arcs, as NetworkX recomputes it.
    let mut length = 0.0;
    for p in path.windows(2) {
        let w = best_pred[p[1] as usize]
            .iter()
            .find(|x| x.0 == p[0])
            .expect("path arc")
            .1;
        length += w;
    }
    Ok((path, length))
}

/// Reverse postorder of a depth-first search from `start` (children in
/// sorted order), the nodes reachable from it.
fn reverse_postorder(out: &Rows, start: usize, n: usize) -> Vec<u32> {
    let mut seen = vec![false; n];
    let mut post = Vec::new();
    let mut stack: Vec<(usize, usize)> = vec![(start, 0)];
    seen[start] = true;
    while let Some(top) = stack.last_mut() {
        let (v, i) = *top;
        let nbrs = out.neighbors(v);
        if i < nbrs.len() {
            top.1 += 1;
            let w = nbrs[i] as usize;
            if !seen[w] {
                seen[w] = true;
                stack.push((w, 0));
            }
        } else {
            post.push(v as u32);
            stack.pop();
        }
    }
    post.reverse();
    post
}

/// Immediate dominator of every node reachable from `start` (the start's
/// is itself), `None` for unreachable nodes. See the module documentation.
pub fn immediate_dominators(g: &Graph, start: usize) -> Result<Vec<Option<u32>>> {
    directed(g, "dominance")?;
    let n = g.node_count();
    if start >= n {
        return Err(Error::InvalidArgument(format!(
            "start {start} is not a node (n = {n})"
        )));
    }
    let out = rows(g, Direction::Out, NeighborOrder::Sorted, true, true);
    let inc = rows(g, Direction::In, NeighborOrder::Sorted, true, true);
    let rpo = reverse_postorder(&out, start, n);
    let mut number = vec![usize::MAX; n];
    for (i, &v) in rpo.iter().enumerate() {
        number[v as usize] = i;
    }
    const UNDEF: usize = usize::MAX;
    let mut idom = vec![UNDEF; n];
    idom[start] = start;
    let intersect = |idom: &[usize], mut a: usize, mut b: usize| {
        while a != b {
            while number[a] > number[b] {
                a = idom[a];
            }
            while number[b] > number[a] {
                b = idom[b];
            }
        }
        a
    };
    let mut changed = true;
    while changed {
        changed = false;
        for &v in rpo.iter().skip(1) {
            let v = v as usize;
            let mut new = UNDEF;
            for &p in inc.neighbors(v) {
                let p = p as usize;
                if idom[p] == UNDEF {
                    continue;
                }
                new = if new == UNDEF {
                    p
                } else {
                    intersect(&idom, p, new)
                };
            }
            if idom[v] != new {
                idom[v] = new;
                changed = true;
            }
        }
    }
    Ok(idom
        .into_iter()
        .map(|d| (d != UNDEF).then_some(d as u32))
        .collect())
}

/// Dominance frontier of every node reachable from `start` (sorted), `None`
/// for unreachable nodes.
pub fn dominance_frontiers(g: &Graph, start: usize) -> Result<Vec<Option<Vec<u32>>>> {
    let idom = immediate_dominators(g, start)?;
    let n = g.node_count();
    let inc = rows(g, Direction::In, NeighborOrder::Sorted, true, false);
    let mut loops = vec![false; n];
    for (&a, &b) in g.edge_sources().iter().zip(g.edge_targets()) {
        if a == b {
            loops[a as usize] = true;
        }
    }
    let mut df: Vec<Vec<u32>> = vec![Vec::new(); n];
    for u in 0..n {
        let Some(du) = idom[u] else { continue };
        let preds = inc.neighbors(u);
        // Join nodes (two or more predecessors, counting a self-loop) and
        // the start, whose own frontier holds itself when it is on a cycle.
        let mut distinct: Vec<u32> = preds.to_vec();
        distinct.dedup();
        let selfloop = loops[u];
        if distinct.len() + selfloop as usize >= 2 || u == start {
            let stop = if u == start { None } else { Some(du) };
            let mut sources = distinct.clone();
            if selfloop {
                sources.push(u as u32);
            }
            for &p in &sources {
                let mut v = p as usize;
                if idom[v].is_none() {
                    continue;
                }
                loop {
                    if Some(v as u32) == stop {
                        break;
                    }
                    df[v].push(u as u32);
                    if v == start {
                        break;
                    }
                    v = idom[v].expect("reachable") as usize;
                }
            }
        }
    }
    Ok((0..n)
        .map(|v| {
            idom[v].map(|_| {
                let mut f = std::mem::take(&mut df[v]);
                f.sort_unstable();
                f.dedup();
                f
            })
        })
        .collect())
}

/// Lowest common ancestor of each pair in a DAG (`None` when the two have
/// no common ancestor). See the module documentation.
pub fn lowest_common_ancestors(
    g: &Graph,
    pairs: &[(usize, usize)],
    order: NeighborOrder,
) -> Result<Vec<Option<u32>>> {
    directed(g, "a lowest common ancestor")?;
    if !is_directed_acyclic_graph(g) {
        return Err(cycle_error());
    }
    let n = g.node_count();
    for &(a, b) in pairs {
        if a >= n || b >= n {
            return Err(Error::InvalidArgument(format!(
                "pair ({a}, {b}) names a node outside 0..{n}"
            )));
        }
    }
    // Ancestors (inclusive) by reachability in the reversed graph.
    let reach = reachability(g);
    let words = (n + 63) / 64;
    let mut anc = vec![vec![0u64; words]; n];
    for (u, row) in (0..n).map(|u| (u, reach.row(u))) {
        for (w, &word) in row.iter().enumerate() {
            let mut bits = word;
            while bits != 0 {
                let b = bits.trailing_zeros() as usize;
                bits &= bits - 1;
                let v = w * 64 + b;
                anc[v][u / 64] |= 1u64 << (u % 64);
            }
        }
        anc[u][u / 64] |= 1u64 << (u % 64);
    }
    let out = rows(g, Direction::Out, order, true, true);
    let mut result = Vec::with_capacity(pairs.len());
    let mut common = vec![0u64; words];
    for &(a, b) in pairs {
        let mut first = None;
        for (i, c) in common.iter_mut().enumerate() {
            *c = anc[a][i] & anc[b][i];
            if first.is_none() && *c != 0 {
                first = Some(i * 64 + c.trailing_zeros() as usize);
            }
        }
        let Some(mut x) = first else {
            result.push(None);
            continue;
        };
        loop {
            let next = out
                .neighbors(x)
                .iter()
                .find(|&&w| common[w as usize / 64] >> (w % 64) & 1 == 1);
            match next {
                Some(&w) => x = w as usize,
                None => break,
            }
        }
        result.push(Some(x as u32));
    }
    Ok(result)
}

/// Lowest common ancestor of each pair in a rooted tree (arcs from parent
/// to child). Without `root`, the tree's unique node without a parent is
/// the root. Fails if the network is not such a tree (NetworkX raises).
pub fn tree_lowest_common_ancestors(
    g: &Graph,
    root: Option<usize>,
    pairs: &[(usize, usize)],
) -> Result<Vec<u32>> {
    directed(g, "a tree lowest common ancestor")?;
    let n = g.node_count();
    if n == 0 {
        return Err(Error::InvalidArgument(
            "lowest common ancestors are not defined for a network with no nodes".into(),
        ));
    }
    let inc = rows(g, Direction::In, NeighborOrder::Sorted, true, true);
    let mut parent = vec![usize::MAX; n];
    let mut roots = Vec::new();
    for (v, slot) in parent.iter_mut().enumerate() {
        match inc.neighbors(v) {
            [] => roots.push(v),
            [p] => *slot = *p as usize,
            _ => {
                return Err(Error::InvalidArgument(format!(
                    "node {v} has several parents, so the network is not a tree; use the DAG \
                     function"
                )))
            }
        }
    }
    if has_loop(g) {
        return Err(cycle_error());
    }
    let root = match root {
        Some(r) => {
            if r >= n {
                return Err(Error::InvalidArgument(format!(
                    "root {r} is not a node (n = {n})"
                )));
            }
            r
        }
        None => match roots.as_slice() {
            [r] => *r,
            [] => return Err(cycle_error()),
            _ => {
                return Err(Error::InvalidArgument(
                    "no root given and the tree has several nodes without a parent".into(),
                ))
            }
        },
    };
    // Depths from the root; nodes outside its subtree cannot be paired.
    let out = rows(g, Direction::Out, NeighborOrder::Sorted, true, true);
    let mut depth = vec![u32::MAX; n];
    depth[root] = 0;
    let mut stack = vec![root];
    while let Some(v) = stack.pop() {
        for &w in out.neighbors(v) {
            let w = w as usize;
            if depth[w] != u32::MAX {
                return Err(cycle_error());
            }
            depth[w] = depth[v] + 1;
            stack.push(w);
        }
    }
    let levels = (usize::BITS - n.leading_zeros()).max(1) as usize;
    let mut up = vec![vec![root; n]; levels];
    for v in 0..n {
        if v != root && parent[v] != usize::MAX {
            up[0][v] = parent[v];
        }
    }
    for k in 1..levels {
        for v in 0..n {
            up[k][v] = up[k - 1][up[k - 1][v]];
        }
    }
    let mut result = Vec::with_capacity(pairs.len());
    for &(a, b) in pairs {
        if a >= n || b >= n || depth[a] == u32::MAX || depth[b] == u32::MAX {
            return Err(Error::InvalidArgument(format!(
                "pair ({a}, {b}) names a node outside the tree rooted at {root}"
            )));
        }
        let (mut x, mut y) = if depth[a] >= depth[b] { (a, b) } else { (b, a) };
        let mut diff = depth[x] - depth[y];
        let mut k = 0;
        while diff > 0 {
            if diff & 1 == 1 {
                x = up[k][x];
            }
            diff >>= 1;
            k += 1;
        }
        if x != y {
            for k in (0..levels).rev() {
                if up[k][x] != up[k][y] {
                    x = up[k][x];
                    y = up[k][y];
                }
            }
            x = up[0][x];
        }
        result.push(x as u32);
    }
    Ok(result)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn graph(n: usize, e: &[(i64, i64)]) -> Graph {
        let (s, t): (Vec<i64>, Vec<i64>) = e.iter().copied().unzip();
        Graph::from_edges(n, &s, &t, None, true).unwrap()
    }

    #[test]
    fn orders() {
        // Diamond 0 -> {2, 1} -> 3, edges given with 2 before 1.
        let g = graph(4, &[(0, 2), (0, 1), (2, 3), (1, 3)]);
        assert_eq!(
            topological_generations(&g, NeighborOrder::Input).unwrap(),
            vec![vec![0], vec![2, 1], vec![3]]
        );
        assert_eq!(
            topological_sort(&g, NeighborOrder::Sorted).unwrap(),
            vec![0, 1, 2, 3]
        );
        let all = all_topological_sorts(&g, NeighborOrder::Input, None).unwrap();
        assert_eq!(all.len(), 2);
        assert!(
            all_topological_sorts(&graph(2, &[(0, 1), (1, 0)]), NeighborOrder::Input, None)
                .is_err()
        );
        assert_eq!(
            lexicographical_topological_sort(&g).unwrap(),
            vec![0, 1, 2, 3]
        );
    }

    #[test]
    fn closure_reduction_and_paths() {
        let g = graph(4, &[(0, 1), (1, 2), (0, 2), (2, 3)]);
        assert_eq!(
            transitive_reduction(&g).unwrap(),
            vec![(0, 1), (1, 2), (2, 3)]
        );
        let c = transitive_closure(&g, Reflexive::Cycles).unwrap();
        assert_eq!(c.len(), 6);
        let cyc = graph(3, &[(0, 1), (1, 0), (1, 2)]);
        let c = transitive_closure(&cyc, Reflexive::Cycles).unwrap();
        assert!(c.contains(&(0, 0)) && c.contains(&(0, 2)) && !c.contains(&(2, 2)));
        let (p, l) = dag_longest_path(&g, false, NeighborOrder::Sorted).unwrap();
        assert_eq!(p, vec![0, 1, 2, 3]);
        assert_eq!(l, 3.0);
    }

    #[test]
    fn dominators_and_ancestors() {
        // 0 -> 1 -> 3, 0 -> 2 -> 3, 3 -> 4, 4 -> 1; 5 unreachable.
        let g = graph(6, &[(0, 1), (1, 3), (0, 2), (2, 3), (3, 4), (4, 1)]);
        let d = immediate_dominators(&g, 0).unwrap();
        assert_eq!(d, vec![Some(0), Some(0), Some(0), Some(0), Some(3), None]);
        let f = dominance_frontiers(&g, 0).unwrap();
        // As NetworkX 3.7 reports.
        assert_eq!(f[1], Some(vec![3]));
        assert_eq!(f[3], Some(vec![1]));
        assert_eq!(f[0], Some(vec![]));
        assert_eq!(f[4], Some(vec![1]));
        assert_eq!(f[5], None);
        let t = graph(5, &[(0, 1), (0, 2), (1, 3), (1, 4)]);
        assert_eq!(
            tree_lowest_common_ancestors(&t, None, &[(3, 4), (3, 2), (1, 1)]).unwrap(),
            vec![1, 0, 1]
        );
        assert_eq!(
            lowest_common_ancestors(&t, &[(3, 4), (2, 4)], NeighborOrder::Sorted).unwrap(),
            vec![Some(1), Some(0)]
        );
    }
}
